package com.otgflasher.pro;import android.app.Activity;import android.os.Bundle;import android.widget.*;import java.io.*;public class PartActivity extends Activity{TextView txtDetail,log;ProgressBar bar;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_part);txtDetail=findViewById(R.id.txt_detail);log=findViewById(R.id.log_view);bar=findViewById(R.id.progress_bar);findViewById(R.id.btn_back).setOnClickListener(v->finish());findViewById(R.id.btn_print_sgdisk_0).setOnClickListener(v->run("sgdisk --print /dev/block/sda"));
findViewById(R.id.btn_print_gdisk_1).setOnClickListener(v->run("gdisk -l /dev/block/sda"));
findViewById(R.id.btn_backup_gpt_2).setOnClickListener(v->run("dd if=/dev/block/sda of=/sdcard/Download/gpt_backup.img bs=512 count=34"));
findViewById(R.id.btn_list_by_name_3).setOnClickListener(v->run("ls -l /dev/block/bootdevice/by-name/"));
}void run(String c){bar.setProgress(5);log.append("\n> "+c+"\n");new Thread(()->{try{Process p=Runtime.getRuntime().exec(new String[]{"sh","-c",c+" 2>&1"});BufferedReader r=new BufferedReader(new InputStreamReader(p.getInputStream()));String l;int pr=5;while((l=r.readLine())!=null){pr+=2;if(pr>95)pr=95;String ll=l;int pp=pr;runOnUiThread(()->{bar.setProgress(pp);txtDetail.setText(pp+"% "+ll);log.append(ll+"\n");});}p.waitFor();runOnUiThread(()->bar.setProgress(100));}catch(Exception e){runOnUiThread(()->log.append("ERR "+e.getMessage()+"\n"));}}).start();}}